<section class="blog-featured"><div class="blog-featured-copy"><p class="blog-kicker"><?=h($featured['category'] ?: 'Novedades')?> <span>·</span> <?=blog_date($featured['published_at'] ?: $featured['created_at'])?></p><h2><a href="blog-post.php?id=<?=(int)$featured['id']?>"><?=h($featured['title'])?></a></h2><p class="blog-excerpt"><?=h($featured['excerpt'])?></p><div class="blog-meta"><span><?= (int)$featured['likes_count'] ?> me gusta</span><span><?= (int)$featured['comments_count'] ?> comentarios</span></div><a class="blog-read-more" href="blog-post.php?id=<?=(int)$featured['id']?>">Continuar leyendo <span aria-hidden="true">→</span></a></div><?php if($featured['cover_image']): ?><a class="blog-featured-image" href="blog-post.php?id=<?=(int)$featured['id']?>"><img src="<?=h($featured['cover_image'])?>" alt="Portada: <?=h($featured['title'])?>"></a><?php endif; ?></section>
<?php if($posts): ?><div class="blog-feed-heading"><h2>Publicaciones anteriores</h2><span><?=count($posts)?> artículos</span></div><div class="blog-feed"><?php foreach($posts as $p): ?><article class="blog-entry"><?php if($p['cover_image']): ?><a class="blog-entry-image" href="blog-post.php?id=<?=(int)$p['id']?>"><img src="<?=h($p['cover_image'])?>" alt="Portada: <?=h($p['title'])?>"></a><?php endif; ?><div class="blog-entry-copy"><p class="blog-kicker"><?=h($p['category'] ?: 'Novedades')?> <span>·</span> <?=blog_date($p['published_at'] ?: $p['created_at'])?></p><h3><a href="blog-post.php?id=<?=(int)$p['id']?>"><?=h($p['title'])?></a></h3><p><?=h($p['excerpt'])?></p><div class="blog-meta"><span><?= (int)$p['likes_count'] ?> me gusta</span><span><?= (int)$p['comments_count'] ?> comentarios</span><a href="blog-post.php?id=<?=(int)$p['id']?>">Continuar leyendo →</a></div></div></article><?php endforeach; ?></div><?php endif; ?>
<?php endif; ?></main>
